<?php if (($data['total'] ?? 0) > ($data['per_page'] ?? 10)): $pages = (int) ceil($data['total'] / $data['per_page']); $query = $_GET; ?>
<nav class="mt-5 flex flex-col gap-3 text-sm sm:flex-row sm:items-center sm:justify-between" aria-label="Pagination"><p class="text-slate-500">Menampilkan <?= e((string) (min($data['total'], (($data['page'] - 1) * $data['per_page']) + 1))) ?>–<?= e((string) min($data['total'], $data['page'] * $data['per_page'])) ?> dari <?= e((string) $data['total']) ?> data</p><div class="flex flex-wrap gap-1"><?php for ($i = max(1, $data['page'] - 2); $i <= min($pages, $data['page'] + 2); $i++): $query['page'] = $i; ?><a href="?<?= e(http_build_query($query)) ?>" <?= $i === $data['page'] ? 'aria-current="page"' : '' ?> class="rounded-lg px-3 py-1.5 <?= $i === $data['page'] ? 'bg-primary text-white' : 'text-slate-600 hover:bg-slate-100' ?>"><?= $i ?></a><?php endfor; ?></div></nav>
<?php endif; ?>
